Geotoolbox
Geotoolbox est une bibliothèque JavaScript développée pour faciliter la manipulation, l’analyse et la visualisation de données géographiques. Elle propose un ensemble d’outils modulaires destinés aux développeurs et aux cartographes, notamment pour le traitement de géométries en GeoJSON, la généralisation, le calcul d’indicateurs spatiaux, ou encore la mise en forme graphique de cartes. Pensée pour s’intégrer facilement dans des projets web, geotoolbox repose sur des standards ouverts et peut être utilisée en complément de bibliothèques comme D3.js ou MapLibre.
👉 Documentation : https://riatelab.github.io/geotoolbox/
POur importer la bibliothèque :
&lt;script src="https://cdn.jsdelivr.net/npm/geotoolbox@3"&gt;&lt;/script&gt;
ou
import { **a function** } from "https://cdn.jsdelivr.net/npm/geotoolbo@3/+esm"
Voici le fond de carte des arrondissements parisiens (affiché avec leaflet)
import { json } from "https://cdn.jsdelivr.net/npm/d3-fetch@3/+esm";
async function DessineParis() {
const data = await json("https://raw.githubusercontent.com/neocarto/Webmapping/refs/heads/main/data/paris.geojson")
const map = L.map('map');
const layer = L.geoJSON(data).addTo(map);
map.fitBounds(layer.getBounds());
}
DessineParis()

Union

import { json } from "https://cdn.jsdelivr.net/npm/d3-fetch@3/+esm"
import { union } from "https://cdn.jsdelivr.net/npm/geotoolbox@3/+esm"
async function DessineParis() {
  const paris = await json("https://raw.githubusercontent.com/neocarto/Webmapping/refs/heads/main/data/paris.geojson")
  const merge = await union(paris)
  const map = L.map('map')
  const layer = L.geoJSON(merge).addTo(map)
  map.fitBounds(layer.getBounds())
}
DessineParis()

Centroid

import { centroid } from "https://cdn.jsdelivr.net/npm/geotoolbox@3/+esm"
const ctr = centroid(paris)

Buffer

import { buffer } from "https://cdn.jsdelivr.net/npm/geotoolbox@3/+esm"
const buff = await buffer(paris, {dist:50})

Border

import { border } from "https://cdn.jsdelivr.net/npm/geotoolbox@3/+esm"
const frontieres = await border(paris)

Nodes

import { nodes } from "https://cdn.jsdelivr.net/npm/geotoolbox@3/+esm"
const points = await nodes(paris)

Convex Hull

import { convexhull } from "https://cdn.jsdelivr.net/npm/geotoolbox@3/+esm"
const convex = await convexhull(ctr)

Concave Hull

import { concavehull } from "https://cdn.jsdelivr.net/npm/geotoolbox@3/+esm"
const concave = await concavehull(ctr)

Simplify

import { json } from "https://cdn.jsdelivr.net/npm/d3-fetch@3/+esm"
import { simplify } from "https://cdn.jsdelivr.net/npm/geotoolbox@3/+esm"
async function DessineParis() {
  const paris = await json("https://raw.githubusercontent.com/neocarto/Webmapping/refs/heads/main/data/paris.geojson")
  const simpl = simplify(paris, {k:0.001})
  const map = L.map('map')
  const layer = L.geoJSON(simpl).addTo(map)
  map.fitBounds(layer.getBounds())
}
DessineParis()
Et si on faisait une simplification interactive ?
&lt;script src="https://unpkg.com/leaflet/dist/leaflet.js"&gt;&lt;/script&gt;
&lt;link rel="stylesheet" href="https://unpkg.com/leaflet/dist/leaflet.css" /&gt;
&lt;div&gt;
  &lt;label for="k"&gt;k : &lt;/label&gt;
  &lt;input type="range" id="k" min="0.0001" max="0.1" value="0.05" step="0.0001"&gt;
  &lt;span id="valeur"&gt;0.2&lt;/span&gt;
&lt;/div&gt;
&lt;div id="map"&gt;&lt;/div&gt;
#map {
    height: 500px;
}
import { json } from "https://cdn.jsdelivr.net/npm/d3-fetch@3/+esm"
import { simplify } from "https://cdn.jsdelivr.net/npm/geotoolbox@3/+esm"

const map = L.map('map')
let layer; // pour stocker la couche

async function DessineParis(k) {
  const paris = await json("https://raw.githubusercontent.com/neocarto/Webmapping/refs/heads/main/data/paris.geojson")
  const simpl = simplify(paris, { k })

  // supprimer la couche précédente si elle existe
  if (layer) {
    map.removeLayer(layer)
  }

  layer = L.geoJSON(simpl).addTo(map)
  map.fitBounds(layer.getBounds())
}

// slider
const slider = document.querySelector("#k")
const valeur = document.querySelector("#valeur")

slider.addEventListener("input", () =&gt; {
  const k = parseFloat(slider.value)
  valeur.textContent = k.toFixed(3)
  DessineParis(k)
})

// initialisation
DessineParis(parseFloat(slider.value))
Problème de ce code : on télécharger le fond de carte à chaque fois qu’on bouge le slider. Ce n’est pas très écolo.
Une solution possible :
import { json } from "https://cdn.jsdelivr.net/npm/d3-fetch@3/+esm"
import { simplify } from "https://cdn.jsdelivr.net/npm/geotoolbox@3/+esm"

const map = L.map('map')
let layer
let original // stockera le GeoJSON original

async function init() {
  // charger une seule fois
  original = await json("https://raw.githubusercontent.com/neocarto/Webmapping/refs/heads/main/data/paris.geojson")
  DessineParis(parseFloat(slider.value))
}

function DessineParis(k) {
  const simpl = simplify(original, { k })

  if (layer) {
    map.removeLayer(layer)
  }

  layer = L.geoJSON(simpl).addTo(map)
  map.fitBounds(layer.getBounds())
}

const slider = document.querySelector("#k")
const valeur = document.querySelector("#valeur")

slider.addEventListener("input", () =&gt; {
  const k = parseFloat(slider.value)
  valeur.textContent = k.toFixed(3)
  DessineParis(k)
})

init()

La géovisualisation prolonge la cartographie thématique en tirant parti des possibilités offertes par le numérique. Comme la cartographie classique, elle vise à représenter et à interpréter des phénomènes géographiques à partir de données, mais elle y ajoute l’interactivité. Grâce aux technologies web, il devient possible d’explorer les données à différentes échelles, de modifier les variables représentées en temps réel, ou encore de croiser cartes et graphiques. La géovisualisation transforme ainsi la carte en un outil d’exploration et d’analyse autant qu’en un support de communication, renouvelant profondément les pratiques de la cartographie thématique à l’ère du numérique.


Tout d’abord, revoyons comment on afficher un geoJSON
&lt;script src="https://unpkg.com/leaflet/dist/leaflet.js"&gt;&lt;/script&gt;
&lt;link rel="stylesheet" href="https://unpkg.com/leaflet/dist/leaflet.css" /&gt;
&lt;div id="map"&gt;&lt;/div&gt;
#map {
    height: 500px;
}
// Modules
import { json } from "https://cdn.jsdelivr.net/npm/d3-fetch@3/+esm";
const d3 = { json };

// Fonction de carto
async function main() {
  const data = await d3.json(
    "https://raw.githubusercontent.com/neocarto/Webmapping/refs/heads/main/data/paris.geojson",
  );
  const map = L.map("map");
  const layer = L.geoJSON(data).addTo(map);
  map.fitBounds(layer.getBounds());
}
// Appel de la fonction
main();
Avec le parametre style, on peut completement configurer la carte. Par exemple, on peut modifier le code précédent en ajoutant :
const style = {
    fillColor: "red",
    weight: 2,
    opacity: 1,
    color: 'white',
    dashArray: '3',
    fillOpacity: 0.7
  }
et
 const layer = L.geoJSON(data, {style}).addTo(map);
1 -Carte choroplethe
Avec leaflet, pour réaliser une carte choroplethe, on a donc besoin d’une foncton qui va affecter une couleur en fonction d’une donnée.
Par exemple :
// Modules
import { json } from "https://cdn.jsdelivr.net/npm/d3-fetch@3/+esm";
const d3 = { json };

// Fonction de carto
async function main() {
  const data = await d3.json(
    "https://raw.githubusercontent.com/neocarto/Webmapping/refs/heads/main/data/paris.geojson",
  );
  console.log(data.features.map((d) =&gt; d.properties));
  const map = L.map("map");
  const layer = L.geoJSON(data, { style }).addTo(map);
  map.fitBounds(layer.getBounds());
}
// Appel de la fonction
main();

// Helpers

function getColor(value) {
  return value &gt; 200000
    ? "#7a0177"
    : value &gt; 150000
      ? "#c51b8a"
      : value &gt; 100000
        ? "#f768a1"
        : value &gt; 50000
          ? "#fa9fb5"
          : value &gt; 25000
            ? "#fcc5c0"
            : "#feebe2";
}

function style(feature) {
  return {
    fillColor: getColor(feature.properties.population), // ou autre attribut
    weight: 1,
    color: "white",
    fillOpacity: 1,
  };
}
NB : Avec des bibliothèques comme statsbreaks ou dicopal, on peut evidemment améliorer la fonction de discrétisation.
On peut aussi utiliser le plugin leaflet-choropleth
&lt;script src="https://unpkg.com/leaflet/dist/leaflet.js"&gt;&lt;/script&gt;
&lt;script src="https://timwis.com/leaflet-choropleth/dist/choropleth.js"&gt;&lt;/script&gt;
&lt;link rel="stylesheet" href="https://unpkg.com/leaflet/dist/leaflet.css" /&gt;
&lt;div id="map"&gt;&lt;/div&gt;
import { json } from "https://cdn.jsdelivr.net/npm/d3-fetch@3/+esm";
const d3 = { json };

async function main() {
  const data = await d3.json(
    "https://raw.githubusercontent.com/neocarto/Webmapping/refs/heads/main/data/paris.geojson",
  );
  console.log(data.features.map((d) =&gt; d.properties));

  // Création de la carte
  const map = L.map("map");

  // Ajout d’un fond
  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
    attribution: "© OpenStreetMap contributors",
  }).addTo(map);

  console.log(data);

  // Création du choroplèthe
  const choropleth = L.choropleth(data, {
    valueProperty: "population", // attribut existant
    scale: ["#f0f9e8", "#08589e"], // gamme de couleurs
    steps: 6,
    mode: "q", // q = quantiles
    style: {
      color: "#fff",
      weight: 1,
      fillOpacity: 0.8,
    },
    onEachFeature: function (feature, layer) {
      layer.bindPopup(
        `&lt;strong&gt;${feature.properties.l_ar}&lt;/strong&gt;&lt;br&gt;Population: ${feature.properties.population}`,
      );
    },
  }).addTo(map);

  // Ajuste le zoom sur la couche
  map.fitBounds(choropleth.getBounds());
}

main();
2 - Cercles proportionnels
&lt;script src="https://unpkg.com/leaflet/dist/leaflet.js"&gt;&lt;/script&gt;
&lt;script src="https://cdn.jsdelivr.net/npm/@turf/turf@7/turf.min.js"&gt;&lt;/script&gt;
&lt;link rel="stylesheet" href="https://unpkg.com/leaflet/dist/leaflet.css" /&gt;
&lt;div id="map"&gt;&lt;/div&gt;
import { json } from "https://cdn.jsdelivr.net/npm/d3-fetch@3/+esm";
const d3 = { json };

async function main() {
  // Chargement du GeoJSON
  const data = await d3.json(
    "https://raw.githubusercontent.com/neocarto/Webmapping/refs/heads/main/data/paris.geojson",
  );

  // Création de la carte
  const map = L.map("map");
  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
    attribution: "© OpenStreetMap contributors",
  }).addTo(map);

  // Ajoute les polygones de base (contours)
  const arrLayer = L.geoJSON(data, {
    style: {
      color: "white",
      weight: 1,
      fillColor: "#ccc",
      fillOpacity: 0.2,
    },
  }).addTo(map);

  map.fitBounds(arrLayer.getBounds());

  // Fonction pour convertir la population en rayon (pixels)
  function getRadius(pop) {
    return Math.sqrt(pop) / 30; // ajuster le diviseur selon l’échelle
  }

  // Boucle sur chaque arrondissement
  data.features.forEach((f) =&gt; {
    const centroid = turf.centroid(f);
    const [lon, lat] = centroid.geometry.coordinates;
    const pop = f.properties.population;

    // Ajoute un cercle proportionnel
    L.circleMarker([lat, lon], {
      radius: getRadius(pop),
      color: "#e41a1c",
      fillColor: "#e41a1c",
      fillOpacity: 0.6,
      weight: 1,
    })
      .bindPopup(`&lt;strong&gt;${f.properties.l_ar}&lt;/strong&gt;&lt;br&gt;Population : ${pop}`)
      .addTo(map);
  });
}

main();
Avec Leaflet, on peut faire beaucpup de choses. Et il existe beaucoup d’exemples en ligne. Par contre, ca necessite de savoir coder. Il n’y a pas de types de cartes thématiques clé en main à Et c’est assez verbeux. Heureusement, il existe d’autres solutions.



geoviz est une bibliothèque JavaScript (en développement) permettant de concevoir des cartes thématiques. Elle fournit un ensemble de fonctions compatibles avec d3. Conçue pour être intuitive et concise, elle permet de gérer différentes couches géographiques (points, lignes, polygones), différents modes de représentations (symboles proportionnels, choroplethe, typologies, symboles, etc) et différentes couches d’habillage (echelle, nord, tuiles, graticule, etc) afin de créer de jolies cartes. Un des principaux avantage est agalement de pouvoir gérer les systèmes de projection. En résumé, les cartes conçues avec geoviz sont :
🌳 Thématiques ✒️ Vectoriales 👆 Interactives ♻️ Interopérables 🔎 Zoomables

Le code est ici : https://github.com/riatelab/geoviz
La documentation est là : https://riatelab.github.io/geoviz/
Et on trouvera ici de nombreux exemples : https://observablehq.com/@neocartocnrs/geoviz

On installe la bibliothèque de la façon suivante :
&lt;script src="https://cdn.jsdelivr.net/npm/geoviz@0.9.4" charset="utf-8"&gt;&lt;/script&gt;
ou
import * as geoviz from "https://cdn.jsdelivr.net/npm/geoviz@0.9.4/+esm";
1 - Principes
Et voici une premiere carte :
&lt;div id = "map"&gt;&lt;/div&gt;
// Les modules
import * as geoviz from "https://cdn.jsdelivr.net/npm/geoviz@0.9.4/+esm";
import { json } from "https://cdn.jsdelivr.net/npm/d3-fetch@3/+esm";
const d3 = { json };

// La fonction de carto
async function drawMap() {
  // Chargement du GeoJSON
  const data = await d3.json(
    "https://raw.githubusercontent.com/neocarto/Webmapping/refs/heads/main/data/paris.geojson",
  );
  // Création de la carte
  let svg = geoviz.create({ domain: data });
  // Ajout d'une couche
  svg.path({ data });
  // Return dans le div
  document.querySelector("#map").append(svg.render());
}
drawMap();
Dans la fonction create'(), on peut definir le domaine d’affichage (domain), la taille de la carte (width), les marges (margin) et la couleur de fond (background). Il est également possible de définir la projection (projection). Pour comprendre comment fonctionnent les projections, vous pouvez regarder ici.
Voici un exemple :
// Les modules
import * as geoviz from "https://cdn.jsdelivr.net/npm/geoviz@0.9.4/+esm";
import { json } from "https://cdn.jsdelivr.net/npm/d3-fetch@3/+esm";
const d3 = { json };

// La fonction de carto
async function drawMap() {
  // Chargement du GeoJSON
  const data = await d3.json(
    "https://raw.githubusercontent.com/neocarto/Webmapping/refs/heads/main/data/world_209.geojson",
  );
  // Création de la carte
  let svg = geoviz.create({ projection: "NaturalEarth1", width: 500 });
  // Ajout d'une couche
  svg.path({ data });
  // Return dans le div
  document.querySelector("#map").append(svg.render());
}
drawMap();
Dans la fonction svg.path(), on peut aussi changer le style de la couche grace aux parametres SVG. Par exemple :
svg.path,({ data, fill:"#CCC", fillOpacity:0.7, stroke:"white" });






